WITH cr_agg AS ( SELECT cr_returned_date_sk, SUM(cr_net_loss) AS cr_net_loss_sum FROM catalog_returns GROUP BY cr_returned_date_sk ), wr_agg AS ( SELECT wr_returned_date_sk, SUM(wr_net_loss) AS wr_net_loss_sum FROM web_returns GROUP BY wr_returned_date_sk ), store_agg AS ( SELECT s_closed_date_sk, COUNT(DISTINCT s_store_sk) AS closed_store_cnt FROM store GROUP BY s_closed_date_sk ) SELECT d.d_date, d.d_year, COALESCE(cr_agg.cr_net_loss_sum, 0) AS catalog_net_loss, COALESCE(wr_agg.wr_net_loss_sum, 0) AS web_net_loss, (COALESCE(cr_agg.cr_net_loss_sum, 0) + COALESCE(wr_agg.wr_net_loss_sum, 0)) AS total_net_loss, COALESCE(store_agg.closed_store_cnt, 0) AS closed_store_count, CASE WHEN (COALESCE(cr_agg.cr_net_loss_sum, 0) + COALESCE(wr_agg.wr_net_loss_sum, 0)) < 1000 THEN 'Low' WHEN (COALESCE(cr_agg.cr_net_loss_sum, 0) + COALESCE(wr_agg.wr_net_loss_sum, 0)) BETWEEN 1000 AND 5000 THEN 'Medium' ELSE 'High' END AS loss_category, RANK() OVER (PARTITION BY d.d_year ORDER BY (COALESCE(cr_agg.cr_net_loss_sum, 0) + COALESCE(wr_agg.wr_net_loss_sum, 0)) DESC) AS loss_rank FROM date_dim d LEFT JOIN cr_agg ON cr_agg.cr_returned_date_sk = d.d_date_sk LEFT JOIN wr_agg ON wr_agg.wr_returned_date_sk = d.d_date_sk LEFT JOIN store_agg ON store_agg.s_closed_date_sk = d.d_date_sk WHERE d.d_year BETWEEN 2020 AND 2023 ORDER BY d.d_year, loss_rank
